/**
 * The Victory
 * -----------
 * The Midianite kings are pursued to Karkor and captured, and Israel is freed for forty years; Gideon refuses the crown. Stage: a desert ford at dawn, the kings in purple caught by the river, the exhausted army triumphant; a man refusing a crown; long light over a quiet land.
 *
 * Palette 0x1a2010 → 0x0a0502 · light: dawn · hero: crown
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, water, army, crown, person } from './gideon-kit.js';

const BG = 0x1a2010;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 3951244055, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x040201, 0x0c0602);
    W.ground(260, 95, 0, 60, 0x0a0502, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x090402, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x060301), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x060301), [0, -0.05, -14.6]);

    /* army: shields and spears in rank */
    army(W, group, -8.0, 29.5, 8, { shields: [0x11150a, 0x090502, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the crown */
    crown(W, group, 0, 1.0, 11, 1.3, { gold: 0x10130a });
    W.disc([0, 4, 1], 4, 0x222a15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.45, s: 1.16 });
    person(W, group, [4.5, 0, 17], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.15, s: 1.09 });

    return W.finish();
}

export default { build };
